import { Component, OnInit } from '@angular/core';
import { RegisterService, RegisterRequest, RegisterResponse, UsernameCheckResponse } from '../../register.service';

interface Task {
  description: string;
  roleName: string;
  selected: boolean;
}

@Component({
  selector: 'app-register',
  templateUrl: './register.component.html',
  styleUrls: ['./register.component.css']
})
export class RegisterComponent implements OnInit {
  ime: string = '';
  username: string = '';
  email: string = '';
  password: string = '';
  confirmPassword: string = '';
  tasks: Task[] = [
    { description: 'Manage portfolios and transactions', roleName: 'Инвеститор', selected: false },
    { description: 'Analyze data trends', roleName: 'Аналитичар', selected: false },
    { description: 'Filter and compare current and historic data trends', roleName: 'Аналитичар', selected: false },
    { description: 'View current and historic data trends', roleName: 'Обичен корисник', selected: false },
    { description: 'Do basic filtering and limited searching', roleName: 'Обичен корисник', selected: false }
  ];
  ulogaNames: string[] = [];
  response: RegisterResponse | null = null;
  error: string | null = null;
  passwordMismatch: boolean = false;
  usernameExists: boolean = false;
  passwordWeak: boolean = false;

  constructor(private registerService: RegisterService) { }

  ngOnInit(): void { }

  validatePasswordStrength(): void {
    const minLength = this.password.length >= 8;
    const hasNumber = /\d/.test(this.password);
    const hasUppercase = /[A-Z]/.test(this.password);
    const hasSpecial = /[!@#$%^&*(),.?":{}|<>]/.test(this.password);
    this.passwordWeak = this.password !== '' && !(minLength && hasNumber && hasUppercase && hasSpecial);
  }

  validatePasswords(): void {
    this.passwordMismatch = this.password !== this.confirmPassword && this.confirmPassword !== '';
  }

  validateUsername(): void {
    if (this.username.trim() === '') {
      this.usernameExists = false;
      return;
    }
    this.registerService.checkUsername(this.username).subscribe({
      next: (response: UsernameCheckResponse) => {
        this.usernameExists = response.exists;
      },
      error: (err) => {
        console.error('Username check failed:', err);
        this.usernameExists = false; // Assume available if check fails to avoid blocking
      }
    });
  }

  updateUlogaNames(): void {
    const selectedRoles = this.tasks.filter(task => task.selected).map(task => task.roleName);
    this.ulogaNames = [...new Set(selectedRoles)]; // Unique role names
  }

  isFormValid(): boolean {
    return this.ime.trim() !== '' &&
      this.username.trim() !== '' &&
      !this.usernameExists &&
      this.email.trim() !== '' &&
      this.password.trim() !== '' &&
      !this.passwordWeak &&
      this.confirmPassword.trim() !== '' &&
      !this.passwordMismatch &&
      this.ulogaNames.length > 0;
  }

  register(): void {
    if (!this.isFormValid()) {
      this.error = 'Please fill all fields correctly and select at least one task.';
      return;
    }

    const request: RegisterRequest = {
      ime: this.ime,
      username: this.username,
      email: this.email,
      password: this.password,
      confirmPassword: this.confirmPassword,
      ulogaNames: this.ulogaNames
    };

    this.registerService.register(request).subscribe({
      next: (response) => {
        this.response = response;
        this.error = null;
        // Reset form
        this.ime = '';
        this.username = '';
        this.email = '';
        this.password = '';
        this.confirmPassword = '';
        this.tasks.forEach(task => task.selected = false);
        this.ulogaNames = [];
        this.passwordMismatch = false;
        this.usernameExists = false;
        this.passwordWeak = false;
      },
      error: (err) => {
        this.response = null;
        this.error = err.error?.message || 'Registration failed';
      }
    });
  }
}
